// clang-format on

namespace {

inline uint16_t swapBytes(uint16_t v) {
    return (v << 8) | (v >> 8);
}

// A byte rides the lane of its parity (13.5.1.1).
inline uint8_t byteOf(const Signals *s) {
    return (s->addr & 1) ? s->data & 0xFF : s->data >> 8;
}

inline bool memRead(const Signals *s) {
    return s->memReq() && s->read();
}

inline bool memWrite(const Signals *s) {
    return s->memReq() && s->write();
}

enum Step : uint8_t { FAIL, OK, SHORT };

// What one attempt marked, so failing undoes only that.
struct Marked {
    uint_fast8_t at[Cycles::MAX_CYCLES];
    uint_fast8_t n = 0;
    void fetch(Signals *s, uint_fast8_t i) { s->markFetch(); at[n++] = i; }
    void byte(Signals *s, uint_fast8_t i) { s->markByte(); at[n++] = i; }
    void operand(Signals *s, uint_fast8_t i) { s->markOperand(); at[n++] = i; }
    void undo(Signals *begin) const {
        for (auto j = 0u; j < n; ++j)
            begin->next(at[j])->clearMark();
    }
};

}  // namespace

const InstZ280::Table *InstZ280::get(uint32_t pc, const Memory &mems) {
    const uint8_t b0 = mems.read_byte(pc);
    const Table *t;
    if (b0 == 0xCB) {
        t = &PAGECB_TABLE[mems.read_byte(pc + 1)];
    } else if (b0 == 0xED) {
        t = &PAGEED_TABLE[mems.read_byte(pc + 1)];
    } else if (b0 == 0xDD || b0 == 0xFD) {
        const uint8_t b1 = mems.read_byte(pc + 1);
        if (b1 == 0xCB) {
            // displacement before the opcode
            const uint8_t op = mems.read_byte(pc + 3);
            t = b0 == 0xDD ? &PAGEDDCB_TABLE[op] : &PAGEFDCB_TABLE[op];
        } else if (b1 == 0xED) {
            const uint8_t op = mems.read_byte(pc + 2);
            t = b0 == 0xDD ? &PAGEDDED_TABLE[op] : &PAGEFDED_TABLE[op];
        } else {
            t = b0 == 0xDD ? &PAGEDD_TABLE[b1] : &PAGEFD_TABLE[b1];
        }
    } else {
        t = &PAGE00_TABLE[b0];
    }
    _len = t->len;
    return t;
}

bool InstZ280::match(Signals *begin, const Signals *end, const Memory &mems) {
    _insufficient = begin->diff(end) < 1;
    _cutShort = false;
    _nexti = 0;
    if (_insufficient || !memRead(begin))
        return false;
    const auto table = get(begin->addr, mems);
    if (_len == 0 || table->seq == 0)
        return false;
    // Alternatives at '@', the taken branch first.
    auto seq = SEQUENCES[table->seq];
    char one[SEQUENCE_MAX + 1];
    while (*seq) {
        const char *at = strchr(seq, '@');
        size_t n = at ? static_cast<size_t>(at - seq) : strlen(seq);
        if (n > SEQUENCE_MAX)
            n = SEQUENCE_MAX;  // a table row longer than any measured
        memcpy(one, seq, n);
        one[n] = 0;
        if (matchSequence(begin, end, one, mems)) {
            _insufficient = false;
            return true;
        }
        if (_insufficient)
            _cutShort = true;  // the ring ended before this one could
        if (at == nullptr)
            break;
        seq = at + 1;
    }
    return false;
}

// One data letter against cycle |i| (and |i|+1 for a split word).
static Step matchData(char c, Signals *begin, uint_fast8_t size,
        uint_fast8_t &i, uint16_t &popped, Marked &marked) {
    auto s = begin->next(i);
    switch (c) {
    case 'B':
        if (!memRead(s))
            return FAIL;
        break;
    case 'R':
        if (!memRead(s))
            return FAIL;
        if (s->wordAccess()) {
            popped = swapBytes(s->data);
        } else if (s->addr & 1) {
            // An odd word is two byte reads; a byte read at an even
            // address is only ever its second half. A lone one is a
            // byte load.
            if (i + 1 >= size)
                return SHORT;
            const auto t = begin->next(i + 1);
            if (memRead(t) && t->byteAccess() && t->addr == s->addr + 1) {
                popped = byteOf(s) | (byteOf(t) << 8);
                t->markOperand();
                ++i;
            }
        }
        break;
    case 'Y':
        if (!memWrite(s) || !s->byteAccess())
            return FAIL;
        break;
    case 'W':
        if (!memWrite(s))
            return FAIL;
        if (s->byteAccess()) {
            if (i + 1 >= size)
                return SHORT;
            const auto t = begin->next(i + 1);
            if (!memWrite(t) || !t->byteAccess() || t->addr != s->addr + 1)
                return FAIL;
            marked.operand(t, i + 1);
            ++i;
        }
        break;
    case 'b':
    case 'r':
        if (!s->ioReq() || !s->read())
            return FAIL;
        break;
    case 'y':
    case 'w':
        if (!s->ioReq() || !s->write())
            return FAIL;
        break;
    case 'a':
        if (!s->intAck())
            return FAIL;
        break;
    default:
        return FAIL;
    }
    marked.operand(s, i);
    ++i;
    return OK;
}

bool InstZ280::matchSequence(Signals *begin, const Signals *end,
        const char *seq, const Memory &mems) {
    const auto size = begin->diff(end);
    const uint32_t base = begin->addr;
    const uint32_t stop = base + _len;  // the first address past it
    uint32_t prefetch = stop;           // the next unfetched address
    uint_fast8_t absorbed = 0;
    uint_fast8_t ahead[PREFETCH_MAX];   // the cycles of that prefetch
    Marked marked;
    uint16_t popped = 0;
    uint_fast8_t i = 0;
    uint_fast8_t foreign = 0;
    _insufficient = false;
    _next = stop;
    LOG_MATCH(cli.print("@@   match: seq="));
    LOG_MATCH(cli.print(seq));
    LOG_MATCH(cli.print(" at "));
    LOG_MATCH(cli.printlnHex(base, 6));

    // Phase 1: the instruction's bytes, one word read each, in order.
    // Marked cycles are the previous instruction's data; a stall may
    // repeat a word already fetched.
    while (isdigit(*seq)) {
        if (i >= size)
            goto insufficient;
        const auto s = begin->next(i);
        const uint32_t want = base + (*seq - '1');
        if (s->isOperand() || s->isByte() || s->fetch()) {
            ++i;
            continue;
        }
        if (memRead(s) && s->addr == want) {
            if (*seq == '1') {
                marked.fetch(s, i);
            } else {
                marked.byte(s, i);
            }
            ++seq;
        } else if (memRead(s) && s->addr < want && s->addr + 8 >= want) {
            marked.byte(s, i);
        } else if (*seq != '1' && foreign < 2 &&
                   !(memRead(s) && s->addr > want && s->addr < want + 8)) {
            // Data of an instruction the ring cut off: let two through.
            ++foreign;
        } else {
            goto not_matched;
        }
        ++i;
    }
    // The next instruction starts here (its bytes are the prefetch,
    // left unmarked), unless a transfer says otherwise.
    _nexti = i;

    // Phase 2: data cycles and the transfer; prefetch and re-fetches
    // absorbed anywhere. A group '{...}' repeats while it matches.
    {
        const char *group = nullptr;  // after '{'
        const char *close = nullptr;  // at '}', while retrying
        uint_fast8_t iter_i = 0, iter_absorbed = 0;
        uint32_t iter_prefetch = 0;
        for (;;) {
            const char c = *seq;
            if (c == 0)
                break;
            if (c == '~') {
                ++seq;
                continue;
            }
            if (c == '{') {
                group = ++seq;
                continue;
            }
            if (c == '}') {
                close = seq;
                iter_i = i;
                iter_absorbed = absorbed;
                iter_prefetch = prefetch;
                seq = group;
                continue;
            }
            Step step = OK;
            if (i >= size) {
                step = SHORT;
            } else {
                auto s = begin->next(i);
                if (s->isOperand() || s->isByte() || s->fetch()) {
                    ++i;
                    continue;
                }
                const bool transfer = strchr("jJkACSi", c) != nullptr;
                uint32_t target = 0;
                if (transfer) {
                    switch (c) {
                    case 'j':
                        target = stop + static_cast<int8_t>(mems.read_byte(stop - 1));
                        break;
                    case 'J':
                        target = mems.read_byte(stop - 2) | mems.read_byte(stop - 1) << 8;
                        break;
                    case 'k':
                        target = stop + static_cast<int16_t>(mems.read_byte(stop - 2) |
                                                             mems.read_byte(stop - 1) << 8);
                        break;
                    case 'C':
                        target = mems.read_byte(base) & 0x38;
                        break;
                    case 'A':
                    case 'S':
                        target = popped;
                        break;
                    default:  // 'i': any read but the prefetch, below
                        break;
                    }
                }
                if (memRead(s)) {
                    // logical vs physical: the page is the MMU's
                    if (transfer && c != 'i' &&
                            (s->addr & 0xFFF) == (target & 0xFFF)) {
                        _next = s->addr;
                        _nexti = i;
                        goto transferred;
                    }
                    if (s->addr == prefetch && absorbed < PREFETCH_MAX) {
                        ahead[absorbed++] = i;  // the next instruction's
                        ++prefetch;
                        ++i;
                        continue;
                    }
                    if (s->addr >= base && s->addr < prefetch) {
                        marked.byte(s, i);  // repeated by a stall or flush
                        ++i;
                        continue;
                    }
                    if (c == 'i') {  // wherever it went
                        _next = s->addr;
                        _nexti = i;
                        goto transferred;
                    }
                    if (transfer)
                        goto not_matched;
                }
                LOG_MATCH(cli.print("         "));
                LOG_MATCH(cli.print(c));
                LOG_MATCH(cli.print(" s="));
                LOG_MATCH(s->print());
                step = transfer ? FAIL : matchData(c, begin, size, i, popped, marked);
            }
            if (step == OK) {
                ++seq;
                continue;
            }
            if (close != nullptr) {
                // no further iteration: back out to after '}''
                while (marked.n && marked.at[marked.n - 1] >= iter_i)
                    begin->next(marked.at[--marked.n])->clearMark();
                i = iter_i;
                absorbed = iter_absorbed;
                prefetch = iter_prefetch;
                seq = close + 1;
                group = close = nullptr;
                continue;
            }
            if (step == SHORT)
                goto insufficient;
            goto not_matched;
        }
    }
    // Trailing re-fetches of the last byte are this instruction's.
    while (i < size) {
        const auto s = begin->next(i);
        if (!memRead(s) || s->addr < base || s->addr >= stop)
            break;
        marked.byte(s, i);
        ++i;
    }
    goto matched;

transferred:
    // Prefetch past a taken transfer is stale.
    for (auto j = 0u; j < absorbed; ++j)
        marked.byte(begin->next(ahead[j]), ahead[j]);
matched:
    LOG_MATCH(cli.print("@@   MATCHED: nexti="));
    LOG_MATCH(cli.printlnDec(_nexti, 2));
    return true;

insufficient:
    _insufficient = true;
not_matched:
    marked.undo(begin);
    LOG_MATCH(cli.print("@@   NOT MATCHED at "));
    LOG_MATCH(cli.println(*seq));
    return false;
}

bool InstZ280::matchInterrupt(
        Signals *begin, const Signals *end, uint32_t expected) {
    // An acknowledge (not for #NMI), the pushes (PC; in mode 3 MSR and
    // identifier), the table reads (modes 2, 3), then the vector fetch.
    const auto size = begin->diff(end);
    uint_fast8_t i = 0;
    _insufficient = false;
    _nexti = 0;
    LOG_MATCH(cli.print("@@ match interrupt at "));
    LOG_MATCH(cli.printlnHex(expected, 6));
    if (i < size && begin->next(i)->intAck())
        ++i;
    uint_fast8_t pushes = 0;
    while (i < size && pushes < 3 && memWrite(begin->next(i)) &&
            begin->next(i)->wordAccess()) {
        const auto s = begin->next(i);
        if (pushes == 0 &&
                (swapBytes(s->data) & 0xFFF) != (expected & 0xFFF))
            return false;
        ++pushes;
        ++i;
    }
    if (pushes == 0)
        return false;  // nothing marked yet
    uint_fast8_t reads = 0;
    while (i < size && reads < 2 && memRead(begin->next(i)) &&
            begin->next(i)->wordAccess()) {
        ++reads;
        ++i;
    }
    if (i >= size) {
        _insufficient = true;
        return false;
    }
    const auto v = begin->next(i);
    if (!memRead(v))
        return false;
    for (auto j = 0u; j < i; ++j)
        begin->next(j)->markOperand();
    _next = v->addr;
    _nexti = i;
    LOG_MATCH(cli.println("@@   MATCHED INTERRUPT"));
    return true;
}

#ifndef ARDUINO
#include <stdio.h>
bool InstZ280::trace = false;
#define TRACE(...) do { if (trace) printf(__VA_ARGS__); } while (0)
#else
#define TRACE(...)
#endif

uint_fast8_t InstZ280::matchAll(Signals *begin, const Signals *end,
        const Memory &mems, uint32_t pc, bool &atPc) {
    const auto cycles = begin->diff(end);
    // A rejected match is skipped on the next pass, which may reject
    // its predecessor in turn: a cut tail unravels from its end.
    bool rejected[Cycles::MAX_CYCLES] = {};
    struct Match {
        uint_fast8_t at;     // the cycle of its fetch
        uint32_t addr;       // of its fetch
        uint32_t expected;   // where the next instruction fetches
        bool interrupted;    // what follows cannot be checked
    } matches[Cycles::MAX_CYCLES];
    uint_fast8_t matched = 0;
    uint32_t expected = begin->addr;
    for (auto pass = 0; pass < 8; ++pass) {
        for (auto j = 0u; j < cycles; ++j)
            begin->next(j)->clearMark();
        matched = 0;
        expected = begin->addr;
        for (auto i = 0u; i < cycles;) {
            auto s = begin->next(i);
            if (s->write() || s->isOperand() || s->isByte() || rejected[i]) {
                ++i;
                continue;
            }
            InstZ280 inst;
            if (inst.match(s, end, mems)) {
                TRACE("  pass %d: %04X at %u, next %04X, nexti %u\n", pass,
                        (unsigned)s->addr, i, (unsigned)inst.nextAddr(), (unsigned)inst.nexti());
                matches[matched++] = {static_cast<uint_fast8_t>(i), s->addr,
                        inst.nextAddr(), inst.cutShort()};
                i += inst.nexti();
                expected = inst.nextAddr();
                continue;
            }
            if (inst.isEnd()) {
                // the ring ends in the next instruction
                TRACE("  pass %d: ring ends in %04X at %u\n", pass, (unsigned)s->addr, i);
                if (matched && (s->addr & 0xFFF) == (expected & 0xFFF))
                    matches[matched - 1].interrupted = true;
                break;
            }
            if (inst.matchInterrupt(s, end, expected)) {
                if (matched)
                    matches[matched - 1].interrupted = true;
                i += inst.nexti();
                expected = inst.nextAddr();
                continue;
            }
            ++i;
        }
        // The last match chains if the ring holds a read where it expects.
        if (matched && !matches[matched - 1].interrupted) {
            auto &last = matches[matched - 1];
            for (auto j = last.at + 1; j < cycles; ++j) {
                const auto s = begin->next(j);
                if (memRead(s) && (s->addr & 0xFFF) == (last.expected & 0xFFF)) {
                    last.interrupted = true;
                    break;
                }
            }
        }
        // Is match k followed by what it expects?
        const auto chains = [&](uint_fast8_t k) {
            const auto &m = matches[k];
            if (m.interrupted)
                return true;
            if (k + 1 < matched)
                return (matches[k + 1].addr & 0xFFF) == (m.expected & 0xFFF);
            return (m.expected & 0xFFF) == (pc & 0xFFF) ||
                   (m.addr & 0xFFF) == (pc & 0xFFF);
        };
        // One of a pair that does not chain is no instruction: the
        // follower if it chains nowhere either, else the one before.
        bool changed = false;
        for (auto k = 0u; k < matched; ++k) {
            if (chains(k))
                continue;
            const auto culprit = (k + 1 < matched && !chains(k + 1)) ? k + 1 : k;
            TRACE("  pass %d: reject %04X at %u\n", pass,
                    (unsigned)matches[culprit].addr, matches[culprit].at);
            rejected[matches[culprit].at] = true;
            changed = true;
            if (culprit == k + 1)
                ++k;
        }
        if (!changed)
            break;
    }
    atPc = matched && ((expected & 0xFFF) == (pc & 0xFFF) ||
                       (matches[matched - 1].addr & 0xFFF) == (pc & 0xFFF));
    return matched;
}

Signals *InstZ280::findFetch(Signals *begin, const Signals *end,
        const Memory &mems, uint32_t pc) {
    const auto cycles = begin->diff(end);
    const auto limit = cycles >= 14 ? 14 : cycles;
    Signals *at = begin->next(cycles);
    uint_fast8_t best = 0;
    bool bestAtPc = false;
    for (auto i = 0u; i < limit; ++i) {
        auto s = begin->next(i);
        bool atPc;
        const auto n = matchAll(s, end, mems, pc, atPc);
        if (n && ((atPc && !bestAtPc) || (atPc == bestAtPc && n > best))) {
            best = n;
            bestAtPc = atPc;
            at = s;
        }
    }
    for (auto j = 0u; j < cycles; ++j)
        begin->next(j)->clearMark();
    if (best) {
        bool atPc;
        matchAll(at, end, mems, pc, atPc);
    }
    return at;
}

